Loss.create!([
  {date: "2016-05-27 04:00:00", amount: "62500000.0", title: "Attendance decreased at NC's Highpoint Market in response to HB2", slug: "highpoint-market", description: "", template: "\nHere's another unfortunate loss for the state of North Carolina.<br><br>\n\nContributing a massive $62,500,000 to the total of $251,663,522, the loss of this  is particularly painful for NC, accounting for 24.835% of the losses to date.\n\n <blockquote class=\"template-quote\">\n\"\"Read more here: http://www.charlotteobserver.com/news/business/article69837702.html#storylink=cpy\"\n<br><br>\n- \n <a class=\"link\" href=\"\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe loss of the Highpoint Market is just one of many recent HB2 related economic downfalls affecting the state of North Carolina.\n", sources: [{"link"=>"http://www.bizjournals.com/triad/news/2016/05/27/high-point-market-attendance-figures-released.html", "meta"=>{"publication"=>"Triad Business Journal", "title"=>"High Point Market attendance figures released", "date"=>"5/27/16", "accessed"=>"9/9/16"}}, {"link"=>"http://www.hickoryrecord.com/news/crowd-thins-slightly-at-nc-furniture-market-after-lgbt-law/article_0063fe40-2429-11e6-bd3a-9baf79980be0.html", "meta"=>{"publication"=>"Hickory Record", "title"=>"Crowd thins slightly at NC furniture market after LGBT law", "date"=>"5/27/16", "accessed"=>"9/9/16"}}, {"link"=>"CUSTOM_CALC"}], active: false, featured: false, short_name: nil},
  {date: "2016-04-04 04:00:00", amount: "3000000.0", title: "Lionsgate moves move shoot out of NC because of HB2", slug: "lionsgate", description: "", template: "\nThings just keep getting worse for the state of NC over HB2.<br><br>\n\nAccounting for nearly 1% of the total losses to the state of North Carolina to date, the  loss of this movie shoot is a painful reality for the state.\n\n <blockquote class=\"template-quote\">\n\"\"We will be hard pressed to continue our relationship with North Carolina if this regressive law remains on the books\"\n<br><br>\n- Lionsgatevia Charlotte Observer\n <a class=\"link\" href=\"http://www.charlotteobserver.com/news/business/article69837702.html\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe loss of the Lionsgate shoot is just one of many recent HB2 related economic downfalls affecting the state of North Carolina.\n", sources: [{"link"=>"http://www.fox46charlotte.com/news/local-news/116956922-story", "meta"=>{"publication"=>"Fox 46 of Charlotte", "title"=>"Lionsgate takes 100 jobs from NC due to HB2", "date"=>"4/4/16", "author"=>"Fox", "accessed"=>"9/9/16"}}, {"link"=>"https://www.americanprogress.org/issues/lgbt/news/2016/04/13/135391/north-carolinas-discriminatory-h-b-2-threatens-more-than-half-billion-dollars-in-economic-activity/", "meta"=>{"publication"=>"Center for American Progress", "title"=>"North Carolina’s Discriminatory H.B. 2 Threatens More Than Half Billion Dollars in Economic Activity", "date"=>"4/13/16", "author"=>"Shabab Ahmed Mirza, Sarah McBride, Laura E. Durso", "accessed"=>"9/9/16"}}], active: false, featured: false, short_name: nil},
  {date: "2016-07-21 04:00:00", amount: "100000000.0", title: "The NBA moves 2017 All-Star Game out of North Carolina in response to HB2", slug: "nba-all-star-game", description: "", template: "\nNC loses even more money due to HB2.<br><br>\n\nContributing a massive $100,000,000 to the total of $251,663,522, the loss of this event hurts North Carolina.\n\n <blockquote class=\"template-quote\">\n\"\"The NBA has decided to relocate the 2017 All-Star Game from Charlotte with the hope of rescheduling for 2019.\n\nSince March, when North Carolina enacted HB2 and the issue of legal protections for the LGBT community in Charlotte became prominent, the NBA and the Charlotte Hornets have been working diligently to foster constructive dialogue and try to effect positive change. We have been guided in these discussions by the long-standing core values of our league. These include not only diversity, inclusion, fairness and respect for others but also the willingness to listen and consider opposing points of view.\n\nOur week-long schedule of All-Star events and activities is intended to be a global celebration of basketball, our league, and the values for which we stand, and to bring together all members of the NBA community -- current and former players, league and team officials, business partners, and fans. While we recognize that the NBA cannot choose the law in every city, state, and country in which we do business, we do not believe we can successfully host our All-Star festivities in Charlotte in the climate created by HB2.\n\nWe are particularly mindful of the impact of this decision on our fans in North Carolina, and who are among the most passionate in our league. It is also important to stress that the City of Charlotte and the Hornets organization have sought to provide an inclusive environment and that the Hornets will continue to ensure that all patrons -- including members of the LGBT community -- feel welcome while attending games and events in their arena.\n\nWe look forward to re-starting plans for our All-Star festivities in Charlotte for 2019 provided there is an appropriate resolution to this matter.\n\nThe NBA will make an announcement on the new location of the 2017 NBA All-Star Game in the coming weeks.\"\n<br><br>\n- NBA\n</blockquote>\n\nThe loss of the NBA All-Star Game is not only a loss for Charlotte, but for the state of North Carolina as a whole.\n", sources: [{"link"=>"http://www.forbes.com/sites/maurybrown/2016/07/22/the-economic-impact-of-charlotte-losing-nba-all-star-game-and-potentially-super-bowls-due-to-hb2/#6e66e6633f60", "meta"=>{"publication"=>"Forbes", "title"=>"The Economic Impact Of Charlotte Losing NBA All-Star Game, And Potentially Super Bowls Due To HB2", "date"=>"7/22/16", "author"=>"Maury Brown", "accessed"=>"9/9/16"}}, {"link"=>"https://www.washingtonpost.com/news/sports/wp/2016/07/21/report-nba-will-move-2017-all-star-game-from-charlotte-to-new-orleans-over-hb2-law/", "meta"=>{"publication"=>"Washington Post", "title"=>"NBA will move 2017 All-Star Game from Charlotte over HB2 law", "date"=>"7/21/16", "author"=>"Tim Bontemps", "accessed"=>"9/9/16"}}, {"link"=>"http://www.espn.com/nba/story/_/id/17120170/nba-moving-all-star-game-charlotte-north-carolina-bill", "meta"=>{"publication"=>"ESPN", "author"=>"NBA", "title"=>"NBA moves 2017 All-Star Game from Charlotte over HB2 bill", "date"=>"7/22/16", "accessed"=>"9/9/16"}}], active: false, featured: false, short_name: nil},
  {date: "2016-05-20 04:00:00", amount: "1365034.125", title: "Citing HB2, Maroon 5 cancels NC shows", slug: "maroon-5", description: "", template: "\nThings just keep getting worse for the state of NC over HB2.<br><br>\n\nAccounting for nearly 1% of the total losses to the state of North Carolina to date, the  loss of this concert is a painful reality for the state.\n\n <blockquote class=\"template-quote\">\n\"\"\"\n<br><br>\n- \n</blockquote>\n\nThis is but one of many recent losses for the state of NC related to HB2.\n", sources: [{"link"=>"http://www.wral.com/maroon-5-cancels-nc-shows-citing-hb2/15716462/", "meta"=>{"publication"=>"WRAL", "title"=>"Citing HB2, Maroon 5 cancels shows in Raleigh and Charlotte", "date"=>"5/20/16", "accessed"=>"9/9/16"}}, {"link"=>"http://www.charlotteobserver.com/entertainment/music-news-reviews/article78823022.html", "meta"=>{"publication"=>"Charlotte Observer", "title"=>"Maroon 5 cancels N.C. shows over HB2, calling decision ‘morally right", "date"=>"5/20/16", "accessed"=>"9/9/16", "author"=>"Theoden Janes"}}, {"link"=>"CUSTOM_CALC", "anchor"=>true}], active: false, featured: false, short_name: nil},
  {date: "2016-04-25 04:00:00", amount: "950000.0", title: "American Institute of Architects moves South Atlantic Region Conference out of Wilmington because of HB2", slug: "aia-conference", description: "", template: "\nNorth Carolina bears the burden of more economic strain over HB2, the controversial \"bathroom bill\" law.<br><br>\n\nAccounting for nearly 0% of the total losses to the state of North Carolina to date, the  loss of this  is but one of many recent hits related to HB2.\n\n <blockquote class=\"template-quote\">\n\"\"\"\n<br><br>\n- \n</blockquote>\n\nThe state continues to lose money over HB2.\n", sources: [{"link"=>"http://www.wilmingtonbiz.com/hospitality/2016/04/26/hb2_loss_of_architect_conference_costs_wilmington_nearly_1m_estimates_show/14705", "meta"=>{"publication"=>"Wilmington Biz", "title"=>"HB2 Loss Of Architect Conference Costs Wilmington Nearly $1M, Estimates Show", "date"=>"4/26/16", "accessed"=>"9/9/16", "author"=>"Cece Nunn"}}, {"link"=>"http://www.aianc.org/government-updates/hb2-our-commitment-to-diversity-and-inclusionary-design-1", "meta"=>{"publication"=>"AIA NC", "title"=>"AIA South Atlantic to Move Conference From Wilmington Due to HB 2", "date"=>"4/25/16", "accessed"=>"9/9/16", "author"=>"David Crawford"}}], active: false, featured: false, short_name: nil},
  {date: "2016-04-12 04:00:00", amount: "21400000.0", title: "HB2 causes cancellation of Deutsche Bank's planned Cary expansion", slug: "deutsche-bank", description: "After freezing jobs expansion in Cary over HB2, Deutsche Bank moves ahead with Florida expansion", template: "\nNC continues to lose money due to the controversial House Bill 2.<br><br>\n\nAccounting for nearly 9% of the total losses to the state of North Carolina to date, the  loss of this company expansion is yet another financial setback for the state over HB2.\n\n <blockquote class=\"template-quote\">\n\"\"We take the commitment to building inclusive work environments seriously. We’re proud of our operations and employees in Cary and regret that as a result of this legislation we are unwilling to include North Carolina in our U.S. expansion plans for now. We very much hope to revisit our plans to grow this location in the near future.\"\n<br><br>\n- John Cryan, Co-Chief Executive Officer of Deutsche Bank.\n <a class=\"link\" href=\"https://www.db.com/usa/content/en/3639.html\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThis is but one of many recent losses for the state of NC related to HB2.\n", sources: [{"link"=>"http://www.bizjournals.com/triangle/news/2016/07/27/three-months-after-hb2-jobs-freeze-in-cary.html", "meta"=>{"publication"=>"Triangle Business Journal", "title"=>"After freezing jobs expansion in Cary over HB2, Deutsche Bank moves ahead with Florida expansion", "date"=>"7/27/16", "author"=>"Lauren K. Ohnesorge", "accessed"=>"9/9/16"}}, {"link"=>"http://www.newsobserver.com/news/business/article71314817.html", "meta"=>{"publication"=>"The News and Observer", "title"=>"Economic impact of HB2 mushrooms in the Triangle", "date"=>"4/12/16", "author"=>"David Bracken and Paul A. Specht", "accessed"=>"9/9/16"}}, {"link"=>"https://www.americanprogress.org/issues/lgbt/news/2016/04/13/135391/north-carolinas-discriminatory-h-b-2-threatens-more-than-half-billion-dollars-in-economic-activity/", "meta"=>{"publication"=>"Center for American Progress", "title"=>"North Carolina’s Discriminatory H.B. 2 Threatens More Than Half Billion Dollars in Economic Activity", "date"=>"4/13/16", "author"=>"Shabab Ahmed Mirza, Sarah McBride, Laura E. Durso", "accessed"=>"9/9/16"}}], active: false, featured: false, short_name: nil},
  {date: "2016-04-08 04:00:00", amount: "700000.0", title: "Bruce Springsteen concert cancelled in protest of House Bill 2", slug: "bruce-springsteen", description: "Springsteen was scheduled to play Greensboro, but said he finds the passing of House Bill 2 unacceptable, and he is doing his part to push back.", template: "\nThe state of North Carolina reports another loss due to HB2.<br><br>\n\nContributing  $700,000 to the total of $251,663,522, the loss of this concert is painful for NC.\n\n <blockquote class=\"template-quote\">\n\"\"Some things are more important than a rock show and this fight against prejudice and bigotry — which is happening as I write — is one of them. It is the strongest means I have for raising my voice in opposition to those who continue to push us backwards instead of forwards.\"\n<br><br>\n- Bruce Springsteen\n <a class=\"link\" href=\"http://brucespringsteen.net/news/2016/a-statement-from-bruce-springsteen-on-north-carolina\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe state continues to lose money over HB2.\n", sources: [{"link"=>"http://money.cnn.com/2016/04/08/media/bruce-springsteen-north-carolina-show-canceled/", "meta"=>{"publication"=>"CNN Money", "title"=>"Bruce Springsteen cancels North Carolina concert over 'bathroom law'", "date"=>"4/8/16", "author"=>"Tom Kludt", "accessed"=>"9/9/16"}}, {"link"=>"https://www.americanprogress.org/issues/lgbt/news/2016/04/13/135391/north-carolinas-discriminatory-h-b-2-threatens-more-than-half-billion-dollars-in-economic-activity/", "meta"=>{"publication"=>"Center for American Progress", "title"=>"North Carolina’s Discriminatory H.B. 2 Threatens More Than Half Billion Dollars in Economic Activity", "date"=>"4/13/16", "author"=>"Shabab Ahmed Mirza, Sarah McBride, Laura E. Durso", "accessed"=>"9/9/16"}}], active: false, featured: false, short_name: nil},
  {date: "2016-05-17 04:00:00", amount: "75900.7925", title: "Itzhak Perlman cancels NC concert in protest of HB2", slug: "itzhak-perlman", description: "", template: "\nNorth Carolina reports further HB2 related losses.<br><br>\n\nContributing  $75,901 to the total of $251,663,522, the loss of this  is painful for NC.\n\n <blockquote class=\"template-quote\">\n\"\"As my fans know, I have spent a lifetime advocating against discrimination towards those with physical disabilities and have been a vocal advocate for treating all people equally. As such, after great consideration, I have decided to cancel my May 18th concert in North Carolina with the North Carolina Symphony as a stand against House Bill 2. As Attorney General Loretta Lynch recently stated, and HB2 “is about a great deal more than just bathrooms. [It] is about the dignity and respect we accord our fellow citizens.” I couldn’t agree more and will look forward to returning to North Carolina when this discriminatory law is repealed.\"\n<br><br>\n- Itzhak Perlmanvia Facebook\n</blockquote>\n\nThe loss of the Itzhak Perlman is not only a loss for Raleigh, but for the state of North Carolina as a whole.\n", sources: [{"link"=>"http://www.jewishjournal.com/culture/article/violinist_itzhak_perlman_scraps_n.c._concert_over_discriminatory_law", "meta"=>{"publication"=>"Jewish Journal", "title"=>"Violinist Itzhak Perlman scraps N.C. concert over ‘discriminatory’ law", "date"=>"5/17/16", "accessed"=>"9/9/16", "author"=>"Colleen Jenkins"}}, {"link"=>"http://www.npr.org/sections/deceptivecadence/2016/05/18/478556368/itzhak-perlman-on-canceling-in-north-carolina-i-had-to", "meta"=>{"publication"=>"NPR", "title"=>"Itzhak Perlman On Canceling In North Carolina: 'I Had To'", "date"=>"5/18/16", "accessed"=>"9/9/16", "author"=>"Anastasia Tsioulcas"}}, {"link"=>"CUSTOM_CALC"}], active: false, featured: false, short_name: nil},
  {date: "2016-04-25 04:00:00", amount: "872221.0", title: "Demi Lovato and Nick Jonas cancel NC concerts in response to HB2", slug: "demi-lovato-nick-jonas", description: "", template: "\nNC loses even more money due to HB2.<br><br>\n\nAccounting for nearly 0% of the total losses to the state of North Carolina to date, the  loss of this concert is yet another financial setback for the state over HB2.\n\n <blockquote class=\"template-quote\">\n\"\"After much thought and deliberation, we have decided to cancel our Honda Civic Tour: Future Now shows in Raleigh and Charlotte. One of our goals for the tour has always been to create an atmosphere where every single attendee feels equal, included, and accepted for who they are.\"\n<br><br>\n- Demi Lovato and Nick Jonasvia Twitter\n <a class=\"link\" href=\"https://twitter.com/ddlovato/status/724705165186457600\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe loss of the Demi Lovato and Nick Jonas marks yet another unnecessary loss for North Carolina.\n", sources: [{"link"=>"http://www.rollingstone.com/music/news/nick-jonas-demi-lovato-cancel-north-carolina-shows-to-protest-hb2-20160425", "meta"=>{"publication"=>"Rolling Stone", "title"=>"Nick Jonas, Demi Lovato Cancel North Carolina Shows to Protest HB2", "date"=>"4/25/16", "accessed"=>"9/9/16", "author"=>"Daniel Kreps"}}, {"link"=>"http://www.charlotteobserver.com/entertainment/music-news-reviews/article73823087.html", "meta"=>{"publication"=>"Charlotte Observer", "title"=>"Demi Lovato, Nick Jonas Charlotte show canceled over HB2", "date"=>"4/25/16", "accessed"=>"9/9/16", "author"=>"Mark Price"}}, {"link"=>"CUSTOM_CALC"}], active: false, featured: false, short_name: nil},
  {date: "2016-04-18 04:00:00", amount: "191000.0", title: "Record Store Day moved from Raleigh to Baltimore over HB2", slug: "record-store-day", description: "", template: "\nThings just keep getting worse for the state of NC over HB2.<br><br>\n\nContributing  $191,000 to the total of $251,663,522, the loss of this  is painful for NC.\n\n <blockquote class=\"template-quote\">\n\"\"We look forward to showing off Raleigh and the true spirit of North Carolina after the repeal of HB2.\n\n\"\n<br><br>\n- Carrie Colliton, Director of Marketing, Department of Record Stores, and co-founder of Record Store Day.\n <a class=\"link\" href=\"\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe state continues to lose money over HB2.\n", sources: [{"link"=>"http://www.newsobserver.com/news/business/article72440452.html", "meta"=>{"publication"=>"News and Observer", "title"=>"HB2 has quadrupled economic losses", "date"=>"4/18/16", "accessed"=>"9/10/16", "author"=>"Paul A. Specht"}}, {"link"=>"http://www.dailykos.com/story/2016/4/19/1517370/-NC-s-HB2-The-Hits-Just-Keep-On-Rolling", "meta"=>{"publication"=>"Daily Kos", "title"=>"NC's HB2 - The Hits Just Keep On Rolling....", "date"=>"4/19/16", "accessed"=>"9/10/16", "author"=>"Lamont Cranston"}}], active: false, featured: false, short_name: nil},
  {date: "2016-04-18 04:00:00", amount: "1100031.101", title: "Boston cancels 3 North Carolina shows on their tour to raise awareness about HB2", slug: "boston", description: "", template: "\nNC loses even more money due to HB2.<br><br>\n\nContributing  $1,100,031 to the total of $251,663,522, the loss of this concert is painful for NC.\n\n <blockquote class=\"template-quote\">\n\"\"While the enjoyment of our fans is our central concern, and we have been looking forward to celebrating forty years of history performing for our listeners in North Carolina with spectacular live shows this spring, human rights are more important.\"\n<br><br>\n- Tom Scholzvia Facebook\n <a class=\"link\" href=\"https://www.facebook.com/bandboston/posts/1176004065772990\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe state continues to lose money over HB2.\n", sources: [{"link"=>"http://www.thetimesnews.com/news/20160418/boston-cancels-three-north-carolina-shows", "meta"=>{"publication"=>"Times News", "title"=>"Boston cancels three North Carolina shows", "date"=>"4/18/16", "accessed"=>"9/10/16"}}, {"link"=>"http://www.charlotteobserver.com/news/business/article72455377.html", "meta"=>{"publication"=>"Charlotte Observer", "title"=>"Boston cancels North Carolina shows because of LGBT law", "date"=>"4/18/16", "accessed"=>"9/10/16", "author"=>"Katherine Peralta"}}, {"link"=>"CUSTOM_CALC"}], active: false, featured: false, short_name: nil},
  {date: "2016-04-26 04:00:00", amount: "1500000.0", title: "Due to HB2, W. K. Kellogg Foundation conference moved out of Asheville", slug: "w-k-kellogg-conference", description: "", template: "\nNorth Carolina bears the burden of more economic strain over HB2, the controversial \"bathroom bill\" law.<br><br>\n\nContributing  $1,500,000 to the total of $251,663,522, the loss of this  hurts North Carolina.\n\n <blockquote class=\"template-quote\">\n\"\"\"\n<br><br>\n- \n</blockquote>\n\nThe W. K. Kellogg Foundation conference in Asheville is just one of recent losses for NC over HB2.\n", sources: [{"link"=>"http://www.citizen-times.com/story/news/local/2016/04/25/hb2-costs-asheville-15m-conference/83513046/", "meta"=>{"publication"=>"Citizen Times", "title"=>"HB2 costs Asheville $1.5M conference", "date"=>"4/26/16", "accessed"=>"9/9/16", "author"=>"John Boyle"}}, {"link"=>"http://wlos.com/news/local/asheville-conference-estimated-to-have-15-million-impact-canceled-due-to-hb2", "meta"=>{"publication"=>"News 13 WLOS", "title"=>"Asheville conference estimated to have $1.5 million impact canceled due to HB2", "date"=>"4/25/16", "accessed"=>"9/9/16", "author"=>"Kimberly King and Krystyna Biassou"}}], active: false, featured: false, short_name: nil},
  {date: "2016-04-22 04:00:00", amount: "337324.2064", title: "Blue Man Group cancels North Carolina shows to protest HB2", slug: "blue-man-group", description: "", template: "\nHere's another unfortunate loss for the state of North Carolina.<br><br>\n\nContributing  $337,324 to the total of $251,663,522, the loss of this show is painful for NC.\n\n <blockquote class=\"template-quote\">\n\"\"We value every individual’s right to live a dignified, vibrant life in full color. As such, we are joining the growing list of entertainment professionals in protest of North Carolina’s HB2 law by canceling our upcoming tour performances in Charlotte.\"\n<br><br>\n- Blue Man Group\n <a class=\"link\" href=\"\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe state continues to lose money over HB2.\n", sources: [{"link"=>"http://www.wral.com/blue-man-group-latest-group-to-cancel-show-over-hb2/15658384/", "meta"=>{"publication"=>"WRAL", "title"=>"Blue Man Group latest performers to cancel show over HB2", "date"=>"4/22/16", "accessed"=>"9/10/16"}}, {"link"=>"http://wncn.com/2016/04/22/blue-man-group-cancels-charlotte-performance-citing-hb2/", "meta"=>{"publication"=>"WNCN", "title"=>"Blue Man Group cancels Charlotte performance citing HB2", "date"=>"4/22/16", "accessed"=>"9/10/16"}}, {"link"=>"CUSTOM_CALC"}], active: false, featured: false, short_name: nil},
  {date: "2016-04-18 04:00:00", amount: "706434.7875", title: "Pearl Jam cancels show, citing HB2", slug: "pearl-jam", description: "", template: "\nThe state of North Carolina reports another loss due to HB2.<br><br>\n\nAccounting for nearly 0% of the total losses to the state of North Carolina to date, the  loss of this  is a painful reality for the state.\n\n <blockquote class=\"template-quote\">\n\"\"The HB2 law that was recently passed is a despicable piece of legislation that encourages discrimination against an entire group of American citizens. The practical implications are expansive and its negative impact upon basic human rights is profound.\"\n<br><br>\n- Pearl Jam\n <a class=\"link\" href=\"https://pearljam.com/news/north-carolina-concert-cancelled\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe Pearl Jam in  is just one of recent losses for NC over HB2.\n", sources: [{"link"=>"http://www.rollingstone.com/music/news/pearl-jam-cancel-raleigh-concert-to-oppose-bathroom-bill-20160418", "meta"=>{"publication"=>"Rolling Stone", "title"=>"Pearl Jame cancel Raleigh concert to oppose 'Bathroom Bill'", "date"=>"4/18/16", "accessed"=>"9/10/16", "author"=>"Daniel Kreps"}}, {"link"=>"http://www.bbc.com/news/world-us-canada-36079415", "meta"=>{"publication"=>"BBC", "title"=>"Pearl Jam cancel North Carolina concert over HB2 law", "date"=>"4/19/16", "accessed"=>"9/10/16"}}, {"link"=>"CUSTOM_CALC"}], active: false, featured: false, short_name: nil},
  {date: "2016-04-13 04:00:00", amount: "348848.5", title: "Ringo Starr cancels NC show in opposition to HB2", slug: "ringo-starr", description: "", template: "\nNorth Carolina reports further HB2 related losses.<br><br>\n\nAccounting for nearly 0% of the total losses to the state of North Carolina to date, the  loss of this concert is yet another financial setback for the state over HB2.\n\n <blockquote class=\"template-quote\">\n\"\"I'm sorry to disappoint my fans in the area, but we need to take a stand against this hatred. Spread peace and love.\"\n<br><br>\n- Ringo Starr\n <a class=\"link\" href=\"http://ymlp.com/zPpUDv\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe Ringo Starr in Cary is just one of recent losses for NC over HB2.\n", sources: [{"link"=>"http://www.washingtontimes.com/news/2016/apr/13/ringo-star-cancels-north-carolina-concert-protest-/", "meta"=>{"publication"=>"Washington Times", "title"=>"Ringo Starr cancels North Carolina concert in protest of transgender bathroom law", "date"=>"4/13/16", "accessed"=>"9/10/16", "author"=>"Bradford Richardson"}}, {"link"=>"http://www.newsweek.com/ringo-starr-cancels-north-carolina-concert-opposition-hb2-bill-447667", "meta"=>{"publication"=>"Newsweek", "title"=>"Ringo Starr cancels North Carolina concert in opposition to HB2 'bathroom' law", "date"=>"4/14/16", "accessed"=>"9/10/16", "author"=>"Tufayel Ahmed"}}, {"link"=>"CUSTOM_CALC"}], active: false, featured: false, short_name: nil},
  {date: "2016-07-13 04:00:00", amount: "1198832.882", title: "Duke vs. Albany Basketball game cancelled over HB2", slug: "duke-vs-albany-basketball", description: "", template: "\nHere's another unfortunate loss for the state of North Carolina.<br><br>\n\nContributing  $1,198,833 to the total of $251,663,522, the loss of this event is painful for NC.\n\n <blockquote class=\"template-quote\">\n\"\"The State University of New York supports Governor Cuomo's executive order banning all non-essential travel to the state of North Carolina.\"\n<br><br>\n- Holly Liapsis, SUNY spokesperson.\n <a class=\"link\" href=\"\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe loss of the Duke Basketball vs. Albany is just one of many recent HB2 related economic downfalls affecting the state of North Carolina.\n", sources: [{"link"=>"http://www.si.com/college-basketball/2016/07/13/albany-duke-canceled-governor-andrew-cuomo-north-carolina-bathroom-law", "meta"=>{"publication"=>"Sports Illustrated", "title"=>"Albany game at Duke canceled over North Carolina HB2 law", "date"=>"7/13/16", "accessed"=>"9/10/16"}}, {"link"=>"http://www.dukechronicle.com/article/2016/07/house-bill-2-leads-to-holes-in-duke-mens-basketball-field-hockey-schedules", "meta"=>{"publication"=>"Duke Chronicle", "title"=>"House Bill 2 leads to holes in Duke men's basketball, field hockey schedules", "date"=>"7/14/16", "accessed"=>"9/10/16"}}, {"link"=>"CUSTOM_CALC"}], active: false, featured: false, short_name: nil},
  {date: "2016-04-05 04:00:00", amount: "44000000.0", title: "PayPal withdraws NC investment over HB2", slug: "paypal", description: "", template: "\nHere's another unfortunate loss for the state of North Carolina.<br><br>\n\nAccounting for nearly 17% of the total losses to the state of North Carolina to date, the  loss of this company expansion is yet another financial setback for the state over HB2.\n\n <blockquote class=\"template-quote\">\n\"\"The new law perpetuates discrimination and it violates the values and principles that are at the core of PayPal’s mission and culture.  As a result, PayPal will not move forward with our planned expansion into Charlotte.\"\n<br><br>\n- Dan Schulman, President and CEO of PayPal.\n <a class=\"link\" href=\"https://www.paypal.com/stories/us/paypal-withdraws-plan-for-charlotte-expansion\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe loss of the Paypal expansion is just one of many recent HB2 related economic downfalls affecting the state of North Carolina.\n", sources: [{"link"=>"http://www.hrc.org/blog/am-equality-tip-sheet-april-5-2016", "meta"=>{"publication"=>"Human Rights Campaign", "title"=>"#AM_Equality Tip Sheet: April 5, 2016", "date"=>"4/5/2016", "author"=>"HRC Staff", "accessed"=>"9/9/16"}}, {"link"=>"https://www.americanprogress.org/issues/lgbt/news/2016/04/13/135391/north-carolinas-discriminatory-h-b-2-threatens-more-than-half-billion-dollars-in-economic-activity/", "meta"=>{"publication"=>"Center for American Progress", "title"=>"North Carolina’s Discriminatory H.B. 2 Threatens More Than Half Billion Dollars in Economic Activity", "date"=>"4/13/2016", "author"=>"Shabab Ahmed Mirza, Sarah McBride, Laura E. Durso", "accessed"=>"9/9/16"}}], active: false, featured: false, short_name: nil},
  {date: "2016-04-08 04:00:00", amount: "180000.0", title: "Southern Sociological Society moves 2019 annual meeting out of Charlotte", slug: "southern-sociological-society", description: "", template: "\nNorth Carolina reports further HB2 related losses.<br><br>\n\nContributing  $180,000 to the total of $251,663,522, the loss of this convention hurts North Carolina.\n\n <blockquote class=\"template-quote\">\n\"\"We don’t want to spend our money in a state that discriminates against the L.G.B.T. community, and since our members often bring their families along to the conferences and stay in the destination for a few days after for fun, we’re talking about tourist dollars from airfare, hotel rooms and meals not going to Charlotte.\"\n<br><br>\n- Dr. Barbara Risman, former President of the Southern Sociological Society.\n <a class=\"link\" href=\"\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe Southern Sociological Society in Charlotte is just one of recent losses for NC over HB2.\n", sources: [{"link"=>"http://www.nytimes.com/2016/04/22/travel/north-carolina-mississippi-lgbt-gay-rights-travel.html", "meta"=>{"publication"=>"New York Times", "title"=>"North Carolina and Mississippi See Tourist Backlash After L.G.B.T. Laws", "date"=>"4/22/16", "accessed"=>"9/10/16", "author"=>"Shivani Vora"}}, {"link"=>"http://www.charlotteobserver.com/news/local/article70867152.html", "meta"=>{"publication"=>"Charlotte Observer", "title"=>"13 groups drop plans for Charlotte events, more could come over HB2", "date"=>"4/8/16", "accessed"=>"9/10/16", "author"=>"David Perlmutt"}}], active: false, featured: false, short_name: nil},
  {date: "2016-04-06 04:00:00", amount: "1275.0", title: "Duck police department cancels spring conference due to HB2", slug: "duck-pd-conference", description: "", template: "\nNC loses even more money due to HB2.<br><br>\n\nContributing  $1,275 to the total of $251,663,522, the loss of this conference is painful for NC.\n\n <blockquote class=\"template-quote\">\n\"\"\"\n<br><br>\n- \n</blockquote>\n\nThe state continues to lose money over HB2.\n", sources: [{"link"=>"http://outerbanksvoice.com/2016/04/06/hb2-results-in-cancellation-of-duck-p-d-sponsored-conference/", "meta"=>{"publication"=>"Outer Banks Voice", "title"=>"HB2 results in cancellation of Duck P.D.-sponsored conference", "date"=>"4/6/16", "accessed"=>"9/10/16", "author"=>"Russ Lay"}}, {"link"=>"CUSTOM_CALC"}], active: false, featured: false, short_name: nil},
  {date: "2016-04-18 04:00:00", amount: "1700000.0", title: "Community Transporation Association of America pulls out of NC over HB2", slug: "community-transportation-association", description: "", template: "\nNorth Carolina bears the burden of more economic strain over HB2, the controversial \"bathroom bill\" law.<br><br>\n\nContributing  $1,700,000 to the total of $251,663,522, the loss of this convention hurts North Carolina.\n\n <blockquote class=\"template-quote\">\n\"\"It's very significant. They were using five of our hotels, and it was a four day convention, so not only are the hotels being impacted, but restaurants, retail establishments, transportation companies. Everyone is going to feel the heat on this.\"\n<br><br>\n- Denny Edwards, CEO, Greater Raleigh Conventions and Visitor's Bureau.\n <a class=\"link\" href=\"http://abc11.com/news/raleigh-business-owner-fears-hb2-shutting-out-customers/1297766/\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe Community Transportation Association of America Event in Raleigh is just one of recent losses for NC over HB2.\n", sources: [{"link"=>"http://www.newsobserver.com/news/business/article72440452.html", "meta"=>{"publication"=>"News and Observer", "title"=>"HB2 has quadrupled economic losses", "date"=>"4/18/16", "accessed"=>"9/10/16", "author"=>"Paul A. Specht"}}, {"link"=>"http://associationsnow.com/2016/04/hb2-costing-north-carolina-business-convention-bureaus-warn/", "meta"=>{"publication"=>"Associations Now", "title"=>"HB2 costing North Carolina business, convention bureaus warn", "date"=>"4/19/16", "accessed"=>"9/10/16", "author"=>"Ernie Smith"}}], active: false, featured: false, short_name: nil},
  {date: "2016-04-15 04:00:00", amount: "9536620.0", title: "Cirque du Soleil pulls NC stops off 2016 tour, citing HB2", slug: "cirque-du-soleil", description: "", template: "\nNC loses even more money due to HB2.<br><br>\n\nContributing  $9,536,620 to the total of $251,663,522, the loss of this show is painful for NC.\n\n <blockquote class=\"template-quote\">\n\"\"Cirque du Soleil strongly believes in diversity and equality for every individual and is opposed to discrimination in any form. The new HB2 legislation passed in North Carolina is an important regression to ensuring human rights for all.\"\n<br><br>\n- Cirque du Soleilvia Facebook\n <a class=\"link\" href=\"https://www.facebook.com/notes/cirque-du-soleil/cirque-du-soleil-will-not-perform-in-north-carolina/10153690474037675\" target=\"_blank\">View full statement ></a>\n</blockquote>\n\nThe state continues to lose money over HB2.\n", sources: [{"link"=>"https://www.washingtonpost.com/news/post-nation/wp/2016/04/15/cirque-du-soleil-cancels-north-carolina-shows-to-protest-lgbt-law/", "meta"=>{"publication"=>"Washington Post", "title"=>"Cirque du Soleil cancels North Carolina shows to protest LGBT law", "date"=>"4/15/16", "accessed"=>"9/10/16", "author"=>"Elahe Izadi"}}, {"link"=>"http://www.wral.com/cirque-du-soleil-cancels-nc-shows-over-hb2/15644282/", "meta"=>{"publication"=>"WRAL", "title"=>"Cirque du Soleil latest to cancel NC shows in protest of HB2", "date"=>"4/15/16", "accessed"=>"9/10/16", "author"=>"Arielle Clay"}}, {"link"=>"CUSTOM_CALC"}], active: false, featured: false, short_name: nil}
